def run(protocol):
    #Load Tips
    tips200= [protocol.load_labware('opentrons_96_tiprack_300ul', '1'), protocol.load_labware('opentrons_96_tiprack_300ul', '2'), protocol.load_labware('opentrons_96_tiprack_300ul', '3')]

    #Load Pipettes

    p300Single = protocol.load_instrument('p300_single', 'left', tip_racks=tips200)

    source_plate =  "moas_12rows"
    dest_plate = "brand_384_wellplate_300ul"

    def load_labware(ind, plate):
        occupied_slots = [transfer_step[ind] for transfer_step in t_list]
        loaded= []
        for slot in occupied_slots:
            if slot not in loaded:
                protocol.load_labware(plate, str(slot))
                loaded.append(slot)
            
    load_labware(0, source_plate)
    load_labware(2, dest_plate)       
    
    def pick(l):
        source_plate, source_well, dest_plate, dest_well, vol = l
        source = protocol.loaded_labwares[int(source_plate)].wells_by_name()[source_well]
        dest = protocol.loaded_labwares[int(dest_plate)].wells_by_name()[dest_well]
        if int(float(vol)) > 40:
            p300Single.pick_up_tip()    
            p300Single.transfer(float(vol), source, dest.bottom(5), new_tip='never', blow_out=False)
            p300Single.mix(1, int(float(vol))/2, dest.bottom(5))
            p300Single.drop_tip() 

    
    for transfers in t_list:
        pick(transfers)
    